[CmdletBinding()]
param()
$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$keys=@('GLPI_API_BASE_URL','GLPI_API_USERNAME','GLPI_API_PASSWORD','GLPI_OAUTH_CLIENT_ID','GLPI_OAUTH_CLIENT_SECRET');$cfg=@{}
Get-Content (Join-Path $root '.env')|%{if($_ -match '^([^#=]+)=(.*)$' -and $keys -contains $matches[1]){$cfg[$matches[1]]=$matches[2]}};$base=$cfg.GLPI_API_BASE_URL.TrimEnd('/');$fields=@('grant_type=password','scope=api',"username=$($cfg.GLPI_API_USERNAME)","password=$($cfg.GLPI_API_PASSWORD)","client_id=$($cfg.GLPI_OAUTH_CLIENT_ID)","client_secret=$($cfg.GLPI_OAUTH_CLIENT_SECRET)");$args=@('-sS','-w',"`n%{http_code}",'-X','POST',"$base/api.php/token",'-H','Accept: application/json','-H','Content-Type: application/x-www-form-urlencoded');foreach($f in $fields){$args+=@('--data-urlencode',$f)};$raw=(& curl.exe @args)-join "`n";$p=$raw-split "`n(?=\d{3}$)";$token=($p[0]|ConvertFrom-Json).access_token;if(!$token){throw 'OAuth failed'};$plain=@{Authorization="Bearer $token";Accept='application/json'}
$entities=Invoke-RestMethod -Method Get -Uri "$base/api.php/v2.3.0/Administration/Entity" -Headers $plain;$profiles=Invoke-RestMethod -Method Get -Uri "$base/api.php/v2.3.0/Administration/Profile" -Headers $plain
$rootEntity=@($entities)|Where-Object {$_.name -match '^Root' -or $_.completename -match '^Root'}|Select-Object -First 1;$admin=@($profiles)|Where-Object {$_.name -ceq 'Admin'}|Select-Object -First 1
"ROOT_ENTITY_ID=$($rootEntity.id) ROOT_ENTITY_NAME=$($rootEntity.name)";"ADMIN_PROFILE_ID=$($admin.id) ADMIN_PROFILE_NAME=$($admin.name)"
$paths=@('Dropdowns/Location','Assets/Computer','Assets/NetworkEquipment','Assistance/Ticket');$sets=@(@{n='NONE';h=$plain},@{n='ENTITY';h=@{Authorization="Bearer $token";Accept='application/json';'GLPI-Entity'=$rootEntity.id}},@{n='ENTITY_RECURSIVE';h=@{Authorization="Bearer $token";Accept='application/json';'GLPI-Entity'=$rootEntity.id;'GLPI-Entity-Recursive'='true'}},@{n='PROFILE';h=@{Authorization="Bearer $token";Accept='application/json';'GLPI-Profile'=$admin.id}},@{n='ENTITY_PROFILE';h=@{Authorization="Bearer $token";Accept='application/json';'GLPI-Entity'=$rootEntity.id;'GLPI-Profile'=$admin.id}},@{n='ALL';h=@{Authorization="Bearer $token";Accept='application/json';'GLPI-Entity'=$rootEntity.id;'GLPI-Profile'=$admin.id;'GLPI-Entity-Recursive'='true'}})
foreach($set in $sets){foreach($path in $paths){$requestArgs=@('-sS','-w',"`n__STATUS__%{http_code}",'-H',"Authorization: $($set.h.Authorization)",'-H','Accept: application/json');foreach($header in @('GLPI-Entity','GLPI-Profile','GLPI-Entity-Recursive')){if($set.h.ContainsKey($header)){$requestArgs+=@('-H',"${header}: $($set.h[$header])")}};$requestArgs+="$base/api.php/v2.3.0/$path?start=0&limit=1";$raw=(& curl.exe @requestArgs)-join "`n";$marker=$raw.LastIndexOf('__STATUS__');$status=$raw.Substring($marker+10).Trim();$body=$raw.Substring(0,$marker).Trim();if($status -eq '200'){"$($set.n) $path HTTP=200"}else{$detail=$null;try{$errorBody=$body|ConvertFrom-Json;$detail=@($errorBody.status,$errorBody.title,$errorBody.detail,$errorBody.message|Where-Object {$_})-join ' | '}catch{};"$($set.n) $path HTTP=$status ERROR=$detail"}}}
